content.arguments:
{"command":"$c=Get-Content "D:\tmp\mino-sdk\real\review_outline.md" -Raw
$files = [regex]::Matches($c,'r\d{2}_\d{4}\.\d{4,5}\.md') | ForEach-Object { $_.Value }
$uniq = $files | Sort-Object -Unique
"Citations (occurrences): " + $files.Count
"Unique files cited: " + $uniq.Count
$all = Get-ChildItem "D:\tmp\mino-sdk\real\set\*.md" | ForEach-Object { $_.Name } | Sort-Object
$missing = $all | Where-Object { $uniq -notcontains $_ }
"Total files in set: " + $all.Count
"Missing from outline: " + ($(if($missing){$missing -join ', '}else{'none'}))","description":"Verify all 32 papers cited in outline"}

